interface GalleryPageProps {
  searchParams: Promise<{
    marble?: string;
    finish?: string;
    useCase?: string;
  }>;
}

async function getGalleryFilterOptions(locale: string): Promise<{
  marbles: Array<{ slug: string; name: string }>;
  finishes: FinishType[];
  useCases: string[];
}>

function useGalleryFilters(): {
  filters: GalleryFilters;
  setFilter: (key: keyof GalleryFilters, value: string | undefined) => void;
  clearFilter: (key: keyof GalleryFilters) => void;
  clearAllFilters: () => void;
  hasActiveFilters: boolean;
  activeFilterCount: number;
}

interface FilterPanelProps {
  filters: GalleryFilters;
  options: {
    marbles: Array<{ slug: string; name: string }>;
    finishes: FinishType[];
    useCases: string[];
  };
  onFilterChange: (key: keyof GalleryFilters, value: string | undefined) => void;
  onClearAll: () => void;
}

interface GalleryEmptyProps {
  hasActiveFilters?: boolean;
  onClearFilters?: () => void;
}
